-- Official UiTM academic catalogue. Source details: database/supabase/academic_catalogue_sources.md
BEGIN;
CREATE TABLE IF NOT EXISTS public.academic_campuses (
  name varchar(100) PRIMARY KEY,
  source_url text NOT NULL
);
CREATE TABLE IF NOT EXISTS public.academic_units (
  name varchar(100) PRIMARY KEY,
  source_url text NOT NULL
);
CREATE TABLE IF NOT EXISTS public.academic_programmes (
  code varchar(12) PRIMARY KEY,
  name varchar(150) NOT NULL,
  unit_name varchar(100) NOT NULL REFERENCES public.academic_units(name),
  level varchar(12) NOT NULL CHECK (level IN ('diploma','degree')),
  source_url text NOT NULL
);
CREATE TABLE IF NOT EXISTS public.academic_offerings (
  campus_name varchar(100) NOT NULL REFERENCES public.academic_campuses(name),
  programme_code varchar(12) NOT NULL REFERENCES public.academic_programmes(code),
  source_url text NOT NULL,
  PRIMARY KEY (campus_name, programme_code)
);
CREATE TABLE IF NOT EXISTS public.academic_coordinator_mappings (
  admin_user_id bigint NOT NULL REFERENCES public.admins(user_id) ON DELETE CASCADE,
  programme_code varchar(12) NOT NULL REFERENCES public.academic_programmes(code),
  campus_name varchar(100) NOT NULL REFERENCES public.academic_campuses(name),
  admin_faculty varchar(100) NOT NULL,
  admin_programme varchar(150) NOT NULL,
  source_url text NOT NULL,
  PRIMARY KEY (admin_user_id, programme_code)
);
CREATE INDEX IF NOT EXISTS idx_academic_programmes_unit ON public.academic_programmes(unit_name, name);
CREATE INDEX IF NOT EXISTS idx_academic_offerings_programme ON public.academic_offerings(programme_code);
CREATE INDEX IF NOT EXISTS idx_academic_coordinator_mapping_scope ON public.academic_coordinator_mappings(campus_name, programme_code);
ALTER TABLE public.students ADD COLUMN IF NOT EXISTS programme_code varchar(12) REFERENCES public.academic_programmes(code);
ALTER TABLE public.student_registration_requests ADD COLUMN IF NOT EXISTS programme_code varchar(12) REFERENCES public.academic_programmes(code);
CREATE INDEX IF NOT EXISTS idx_students_programme_code ON public.students(programme_code);
ALTER TABLE public.academic_campuses ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.academic_units ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.academic_programmes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.academic_offerings ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.academic_coordinator_mappings ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.academic_campuses, public.academic_units, public.academic_programmes, public.academic_offerings, public.academic_coordinator_mappings FROM PUBLIC, anon, authenticated;
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='internpilih_app') THEN
    GRANT SELECT ON public.academic_campuses, public.academic_units, public.academic_programmes, public.academic_offerings, public.academic_coordinator_mappings TO internpilih_app;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='internpilih_backend') THEN
    GRANT SELECT ON public.academic_campuses, public.academic_units, public.academic_programmes, public.academic_offerings, public.academic_coordinator_mappings TO internpilih_backend;
  END IF;
END $$;
ON CONFLICT (name) DO NOTHING;
ON CONFLICT (name) DO NOTHING;
ON CONFLICT (code) DO NOTHING;
ON CONFLICT (campus_name,programme_code) DO NOTHING;
ON CONFLICT (campus_name,programme_code) DO NOTHING;
SELECT a.user_id,v.programme_code,v.campus_name,v.admin_faculty,v.admin_programme,v.source_url
FROM (VALUES
  ('CS251','Arau','Faculty of Computer and Mathematical Sciences','Bachelor of Computer Science with Honours (Netcentric Computing)','https://fskmperlis.uitm.edu.my/programme/'),
  ('SR243','Arau','Faculty of Sports Science and Recreation','Bachelor of Sports Science with Honours','https://mediaserveroa.uitm.edu.my/prod/bpp_syarat/syarat/UITM-TABURAN-SARJANA-MUDA.pdf'),
  ('AM238','Kota Kinabalu','Faculty of Administrative Science and Policy Studies','Bachelor of Administrative Science with Honours','https://mediaserveroa.uitm.edu.my/prod/bpp_syarat/syarat/UITM-TABURAN-SARJANA-MUDA.pdf'),
  ('AC240','Puncak Alam','Faculty of Accountancy','Bachelor of Accountancy with Honours','https://mediaserveroa.uitm.edu.my/prod/bpp_syarat/syarat/UITM-TABURAN-SARJANA-MUDA.pdf'),
  ('CS230','Shah Alam','Faculty of Computer and Mathematical Sciences','Bachelor of Computer Science with Honours','https://mediaserveroa.uitm.edu.my/prod/bpp_syarat/syarat/UITM-TABURAN-SARJANA-MUDA.pdf')
) AS v(programme_code,campus_name,admin_faculty,admin_programme,source_url)
JOIN public.admins a ON a.campus=v.campus_name AND a.faculty=v.admin_faculty AND a.programme=v.admin_programme
JOIN public.users u ON u.id=a.user_id AND u.role='admin'
JOIN public.academic_offerings o ON o.campus_name=v.campus_name AND o.programme_code=v.programme_code
ON CONFLICT (admin_user_id,programme_code) DO NOTHING;
COMMIT;
